```cpp
#include <iostream>
#include <fstream>
using namespace std;

int cross(int ox, int oy, int ax, int ay, int bx, int by) {
    return (ax - ox) * (by - oy) - (ay - oy) * (bx - ox);
}

int dist2(int ax, int ay, int bx, int by) {
    return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
}

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int px[100], py[100];
    for (int i = 0; i < n; i++) plik >> px[i] >> py[i];
    int start = 0;
    for (int i = 1; i < n; i++) {
        if (py[i] < py[start] || (py[i] == py[start] && px[i] < px[start]))
            start = i;
    }
    int hull[100], hullSize = 0;
    int cur = start;
    do {
        hull[hullSize++] = cur;
        int next = (cur == 0) ? 1 : 0;
        for (int i = 0; i < n; i++) {
            if (i == cur) continue;
            int c = cross(px[cur], py[cur], px[next], py[next], px[i], py[i]);
            if (c < 0 || (c == 0 && dist2(px[cur], py[cur], px[i], py[i]) > dist2(px[cur], py[cur], px[next], py[next]))) {
                next = i;
            }
        }
        cur = next;
    } while (cur != start);
    cout << "Otoczka wypukla:" << endl;
    for (int i = 0; i < hullSize; i++) {
        cout << "(" << px[hull[i]] << "," << py[hull[i]] << ")" << endl;
    }
    cout << "Liczba wierzcholkow: " << hullSize << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm Jarvisa (gift wrapping) zaczyna od punktu o najnizszym y i w kazdym kroku wybiera punkt tworzacy najbardziej prawy skret (CW). Iloczyn wektorowy cross(cur, best, i) < 0 oznacza ze i jest bardziej CW niz best. Zlozonosc O(n*h) gdzie h to liczba wierzcholkow otoczki.

Weryfikacja:
- Start: (0,0) — najnizsze y=0, najnizsze x=0.
- Z (0,0): next = (4,0). Zaden punkt nie daje cross < 0, wiec next = (4,0).
- Z (4,0): next = (5,3). Cross(4,0, init, 5,3) daje CW skret.
- Z (5,3): next = (3,5). Najbardziej CW.
- Z (3,5): next = (0,4). Najbardziej CW.
- Z (0,4): next = (0,0) = start. Koniec.
- Hull: (0,0), (4,0), (5,3), (3,5), (0,4). 5 wierzcholkow.
- Punkty wewnetrzne: (2,1), (3,2), (1,3) — nie naleza do otoczki.
